const flowMat = new THREE.MeshBasicMaterial({ color: 0x6fb3d8 });

function arcPoints(r, a0, a1, n = 24) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n);
    // CCW about +Y (right-hand rule): theta increases => x=cos, z=-sin
    pts.push(new THREE.Vector3(r * Math.cos(a), 0, -r * Math.sin(a)));
  }
  return pts;
}

function addFlowArc(r, a0, a1, withHead) {
  const pts = arcPoints(r, a0, a1);
  const curve = new THREE.CatmullRomCurve3(pts);
  flowGroup.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 32, 0.03, 6), flowMat));
  if (withHead) {
