    const a = a1;
    const tangent = new THREE.Vector3(-Math.sin(a), 0, -Math.cos(a)); // d/dtheta
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.09, 0.24, 10), flowMat);
    head.position.copy(end).addScaledVector(tangent, 0.1);
    head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tangent);
    flowGroup.add(head);
