const lblP0 = addLabel('<i>P</i><sub>0</sub>', new THREE.Vector3(0, -0.32, 0), { fontSize: '16px', bold: true });
const lblCurl = addLabel('Curl <b>F</b>(<i>P</i><sub>0</sub>)', new THREE.Vector3(0, 1.2, 0), { fontSize: '15px' });
computeCurl();

/* ── Drag P0 on the y=0 plane ────────────────────────────────────────────── */
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
let dragging = false;

canvas.addEventListener('pointerdown', (e) => {
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRay.setFromCamera(dragPtr, camera);
  if (dragRay.intersectObject(p0Hit, false).length) {
    dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture(e.pointerId);
    tweenTarget = null;
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRay.setFromCamera(dragPtr, camera);
  const hit = new THREE.Vector3();
  if (dragRay.ray.intersectPlane(dragPlane, hit)) {
    const r = Math.hypot(hit.x, hit.z);
    if (r > 4) { hit.x *= 4 / r; hit.z *= 4 / r; }
    paddle.position.set(hit.x, 0, hit.z);
    computeCurl();
  }
});
window.addEventListener('pointerup', () => { dragging = false; controls.enabled = true; });

/* ── Slider ──────────────────────────────────────────────────────────────── */
const slider = document.getElementById('rotationRate');
slider.addEventListener('input', () => { S = parseFloat(slider.value); computeCurl(); });

/* ── Demo steps ──────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Paddle wheel in the vortex', S: 1.5, p0: [0, 0],
    text: 'At the field center the swirling flow catches the pitched blades and the wheel spins counterclockwise. The curl vector points straight up along the spindle — the axis of maximum circulation.' },
  { title: 'Weak circulation', S: 0.4, p0: [0, 0],
    text: 'Lowering the rotation rate makes the paddle creep and the Curl F(P\u2080) arrow shrink: curl measures the density of circulation, not the flow\u2019s speed at one point.' },
  { title: 'Strong circulation', S: 2.5, p0: [0, 0],
    text: 'At a high rotation rate the blades whirl and the curl arrow stretches upward — its length is twice the paddle\u2019s angular speed.' },
  { title: 'Drag P\u2080 off-center', S: 1.5, p0: [3.4, 0],
    text: 'P\u2080 slides outward across the fixed flow pattern. The spin slows, stops entirely near r = 2.8 where the local curl is zero, then reverses — the arrow flips downward and the wheel turns clockwise. Try dragging P\u2080 yourself!' },
];
let stepIdx = 0, tweenTarget = null;

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.text;
  slider.value = st.S; S = st.S;
  tweenTarget = { x: st.p0[0], z: st.p0[1], t: 0 };
  computeCurl();
}
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── Per-frame update (spin + tween) ─────────────────────────────────────── */
let lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  if (tweenTarget) {
    tweenTarget.t += dt / 3;
    const k = Math.min(1, tweenTarget.t);
    paddle.position.x += (tweenTarget.x - paddle.position.x) * Math.min(1, k * 0.2 + dt * 2);
    paddle.position.z += (tweenTarget.z - paddle.position.z) * Math.min(1, k * 0.2 + dt * 2);
    computeCurl();
    if (k >= 1) tweenTarget = null;
  }
  blades.rotation.y += omega * dt;   // spin pauses automatically when omega = 0
})();
// @FIGURE_CODE_END

