userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>Rotation rate S
  <input type="range" id="rotationRate" min="0" max="3" step="0.1" value="1.5">
</label>
<div id="curlReadout" style="font-size:11px;color:#333;">curl = 3.00, &Omega; = 1.50</div>
<hr style="width:100%;border:0;border-top:1px solid #ddd;">
<div style="font-weight:bold;font-size:12px;">Guided tour</div>
<div id="stepTitle" style="font-weight:bold;"></div>
<div id="stepText" style="font-size:11px;color:#444;line-height:1.4;"></div>
<div style="display:flex;gap:4px;">
  <button id="btnPrevStep">&larr; Prev</button>
  <button id="btnNextStep">Next &rarr;</button>
</div>
<div style="font-size:10px;color:#777;">Tip: drag the black P&#8320; sphere across the flow plane; orbit to compare the upright paddle vanes with the perpendicular curl axis.</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// Element spec:
//   P0            -> SphereGeometry(0.12) black, draggable with transparent hit proxy
//   spindle       -> CylinderGeometry(0.035,0.035,1.75) dark grey, y in [-0.25,1.5]
//   curl arrow    -> Group(unit +Y arrow: cyl shaft r0.05 + cone head), scaled/flipped by local curl
//   rotation arc  -> TubeGeometry broken arc r=0.58 at y=1.58, black, large cone arrowhead, CCW from +Y
//   blades        -> 4 upright vanes: BoxGeometry(1.12,0.74,0.035) salmon #f2c1a7, dark edges, radial at 0/90/180/270
//   flow arcs     -> TubeGeometry broken arcs r=1.6/2.4/3.2 in XZ plane y=0, #6fb3d8, cone arrowheads, CCW
//   background    -> white; no ground plane, matching source

const D2R = Math.PI / 180;

scene.add(new THREE.AmbientLight(0xffffff, 0.78));
const _sun = new THREE.DirectionalLight(0xffffff, 0.85);
_sun.position.set(3, 6, 4);
scene.add(_sun);

/* ── Fixed flow field: broken concentric arcs, CCW viewed from +Y ────────── */
const flowGroup = new THREE.Group();
scene.add(flowGroup);
const flowMat = new THREE.MeshBasicMaterial({ color: 0x6fb3d8 });

function arcPoints(r, a0, a1, y = 0, n = 28) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n);
    // Positive rotation about +Y: theta increases => x=cos, z=-sin.
    pts.push(new THREE.Vector3(r * Math.cos(a), y, -r * Math.sin(a)));
  }
  return pts;
}

function tangentAt(a) {
  return new THREE.Vector3(-Math.sin(a), 0, -Math.cos(a)).normalize();
}

function addArcTube(r, a0, a1, y, tubeR, mat, withHead, headScale = 1) {
  const pts = arcPoints(r, a0, a1, y);
  const curve = new THREE.CatmullRomCurve3(pts);
  flowGroup.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 36, tubeR, 7), mat));
  if (withHead) {
    const end = pts[pts.length - 1];
    const tan = tangentAt(a1);
    const head = new THREE.Mesh(new THREE.ConeGeometry(0.095 * headScale, 0.28 * headScale, 12), mat);
    head.position.copy(end).addScaledVector(tan, 0.10 * headScale);
    head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
    flowGroup.add(head);
  }
}

[1.6, 2.4, 3.2].forEach((r, ri) => {
  // Three broken strokes per ring; offsets keep the gaps staggered like the source.
  const off = ri * 38 * D2R;
  for (let k = 0; k < 3; k++) {
    const a0 = off + k * 120 * D2R + 10 * D2R;
    const a1 = off + k * 120 * D2R + 96 * D2R;
    addArcTube(r, a0, a1, 0, 0.034, flowMat, k !== 1, 1.0);
  }
});

/* ── Draggable paddle-wheel assembly (local origin = P0) ─────────────────── */
const paddle = new THREE.Group();
scene.add(paddle);

const darkMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const blackMat = new THREE.MeshStandardMaterial({ color: 0x111111 });

const p0 = new THREE.Mesh(new THREE.SphereGeometry(0.12, 24, 16), blackMat);
paddle.add(p0);
const p0Hit = new THREE.Mesh(
  new THREE.SphereGeometry(0.42, 12, 8),
  new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, depthWrite: false })
);
paddle.add(p0Hit);

const spindle = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 1.75, 12), darkMat);
spindle.position.y = 0.625;
paddle.add(spindle);

// Curl arrow: unit +Y arrow with base at P0; scale.y sets length, rotation.z flips for negative curl.
const curlArrow = new THREE.Group();
const arrowMat = new THREE.MeshStandardMaterial({ color: 0x1a1a1a, side: THREE.DoubleSide });
const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.72, 12), arrowMat);
shaft.position.y = 0.36;
const cone = new THREE.Mesh(new THREE.ConeGeometry(0.14, 0.30, 16), arrowMat);
cone.position.y = 0.72 + 0.15;
curlArrow.add(shaft, cone);
paddle.add(curlArrow);

// Larger, clearer curved rotation arrow around the upper spindle.
{
  const r = 0.58, y = 1.58;
  const a0 = -205 * D2R, a1 = 95 * D2R; // 300-degree sweep, gap at front-right
  const pts = arcPoints(r, a0, a1, y, 40);
  const curve = new THREE.CatmullRomCurve3(pts);
  paddle.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 48, 0.035, 8), blackMat));
  const tan = tangentAt(a1);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.34, 14), blackMat);
  head.position.copy(pts[pts.length - 1]).addScaledVector(tan, 0.13);
  head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tan);
  paddle.add(head);
}

// Four upright vanes radiating from the spindle: vertical rectangular plates, not horizontal pitched boxes.
const blades = new THREE.Group();
paddle.add(blades);
const bladeMat = new THREE.MeshStandardMaterial({ color: 0xf2c1a7, side: THREE.DoubleSide });
const edgeMat = new THREE.LineBasicMaterial({ color: 0x4a3a32 });
const bladeGeom = new THREE.BoxGeometry(1.12, 0.74, 0.035); // radial length x height x thin thickness
const bladeEdges = new THREE.EdgesGeometry(bladeGeom);
for (let k = 0; k < 4; k++) {
  const holder = new THREE.Group();
  holder.rotation.y = k * Math.PI / 2;
  const innerR = 0.24;                 // visible separation from the spindle
  const centerR = innerR + 1.12 / 2;   // 0.80
  const mesh = new THREE.Mesh(bladeGeom, bladeMat);
  mesh.position.set(centerR, 0.39, 0); // lower edge just above the flow plane
  const edges = new THREE.LineSegments(bladeEdges, edgeMat);
  edges.position.copy(mesh.position);
  holder.add(mesh, edges);
  blades.add(holder);
}

registerInteractive(p0Hit, {
  title: 'Paddle wheel at P\u2080',
  tooltip: 'Drag P\u2080 across the flow',
  body: 'A tiny paddle wheel immersed in the flow. Its spindle points along curl F(P\u2080), and its angular speed \u03a9 equals half the local curl magnitude. Drag it: the spin slows, stops near r \u2248 2.8, and reverses beyond.',
});

/* ── Field math and readout ──────────────────────────────────────────────── */
let S = 1.5, c = 0, omega = 0;
const readout = document.getElementById('curlReadout');

function computeCurl() {
  const px = paddle.position.x, pz = paddle.position.z;
  const r2 = px * px + pz * pz;
  const r = Math.sqrt(r2);
  c = S * Math.exp(-r2 / 8) * (2 - r2 / 4);
  omega = c / 2;

  const mag = Math.abs(c);
  curlArrow.visible = mag > 0.035;
  const L = Math.min(2.1, Math.max(0.16, 0.55 * mag));
  curlArrow.rotation.z = c < 0 ? Math.PI : 0;
  curlArrow.scale.set(1, L, 1);

  lblCurl.pos.set(px, (c < 0 ? -L - 0.46 : L + 0.34), pz);
  lblP0.pos.set(px, -0.34, pz);
  readout.innerHTML =
    'r = ' + r.toFixed(2) +
    ' &nbsp; curl = ' + c.toFixed(2) +
    ' &nbsp; &Omega; = ' + omega.toFixed(2) + (c < 0 ? ' (reversed)' : '');
}

/* ── Camera after geometry, then HTML labels ─────────────────────────────── */
setCameraView({ projection: 'perspective', azimuthDeg: 45, elevationDeg: 22, rollDeg: 0, heightFraction: 0.65 });

const lblP0 = addLabel('<i>P</i><sub>0</sub>', new THREE.Vector3(0, -0.34, 0), { fontSize: '18px', bold: true });
lblP0.div.style.fontFamily = 'Georgia, serif';
const lblCurl = addLabel('Curl <b>F</b>(<i>P</i><sub>0</sub>)', new THREE.Vector3(0, 1.9, 0), { fontSize: '20px' });
lblCurl.div.style.fontFamily = 'Georgia, serif';
computeCurl();

/* ── Drag P0 on the y=0 plane, clamped to radius 4 ───────────────────────── */
const dragRay = new THREE.Raycaster();
const dragPtr = new THREE.Vector2();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
let dragging = false;

function setDragPtr(e) {
  const rect = canvas.getBoundingClientRect();
  dragPtr.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
  dragPtr.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
  dragRay.setFromCamera(dragPtr, camera);
}

canvas.addEventListener('pointerdown', (e) => {
  setDragPtr(e);
  if (dragRay.intersectObject(p0Hit, false).length) {
    dragging = true;
    controls.enabled = false;
    canvas.setPointerCapture(e.pointerId);
    tweenTarget = null;
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!dragging) return;
  setDragPtr(e);
  const hit = new THREE.Vector3();
  if (dragRay.ray.intersectPlane(dragPlane, hit)) {
    const r = Math.hypot(hit.x, hit.z);
    if (r > 4) { hit.x *= 4 / r; hit.z *= 4 / r; }
    paddle.position.set(hit.x, 0, hit.z);
    computeCurl();
  }
});
window.addEventListener('pointerup', () => { dragging = false; controls.enabled = true; });

/* ── Slider ──────────────────────────────────────────────────────────────── */
const slider = document.getElementById('rotationRate');
slider.addEventListener('input', () => { S = parseFloat(slider.value); computeCurl(); });

/* ── Guided tour ─────────────────────────────────────────────────────────── */
const steps = [
  { title: 'Paddle wheel in the vortex', S: 1.5, p0: [0, 0],
    text: 'At the field center the swirling flow catches the upright vanes and the wheel spins counterclockwise. The curl vector points straight up along the spindle — the axis of maximum circulation.' },
  { title: 'Weak circulation', S: 0.4, p0: [0, 0],
    text: 'Lowering the rotation rate makes the paddle creep and the Curl F(P\u2080) arrow shrink: curl measures the density of circulation, not the flow\u2019s speed at one point.' },
  { title: 'Strong circulation', S: 2.5, p0: [0, 0],
    text: 'At a high rotation rate the vanes whirl and the curl arrow stretches upward — its length is twice the paddle\u2019s angular speed.' },
  { title: 'Drag P\u2080 off-center', S: 1.5, p0: [3.4, 0],
    text: 'P\u2080 slides outward across the fixed flow pattern. The spin slows, stops entirely near r = 2.8 where the local curl is zero, then reverses — the arrow flips downward and the wheel turns clockwise. Try dragging P\u2080 yourself!' },
];
let stepIdx = 0, tweenTarget = null;

function goToStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  const st = steps[stepIdx];
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.title;
  document.getElementById('stepText').textContent = st.text;
  slider.value = st.S; S = st.S;
  tweenTarget = { x: st.p0[0], z: st.p0[1], t: 0 };
  computeCurl();
}
document.getElementById('btnPrevStep').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNextStep').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

/* ── Per-frame update (spin + tween) ─────────────────────────────────────── */
let lastT = performance.now();
(function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - lastT) / 1000);
  lastT = now;
  if (tweenTarget) {
    tweenTarget.t += dt / 3;
    const k = Math.min(1, tweenTarget.t);
    const ease = Math.min(1, k * 0.25 + dt * 2.2);
    paddle.position.x += (tweenTarget.x - paddle.position.x) * ease;
    paddle.position.z += (tweenTarget.z - paddle.position.z) * ease;
    computeCurl();
    if (k >= 1) tweenTarget = null;
  }
  blades.rotation.y += omega * dt;   // spin pauses automatically when omega = 0
})();
// @FIGURE_CODE_END

Output ONLY the JSON evaluation object.

systemPrompt:
You are the orchestration agent for an iterative figure-generation loop. Generation works by taking an original 2D figure, making a generation plan, generating an interactive 3D figure, and evaluating it.

You will receive the critic evaluation, including failure modes, scores, notes, and action items.
Your job is to decide which part of the system is most responsible for the problem:
- planner: the interaction plan or conceptual decomposition is wrong, incomplete, or missing the right elements
- generator: the plan is close to right, but the rendered implementation, labels, layout, interactivity, or execution is broken
- none: the figure is good enough to stop iterating

Use the failure modes and action items as the primary evidence. Do not decide from raw score thresholds alone.
Prefer planner when the critic indicates concept misunderstanding, missing core elements, wrong primitives, or the wrong overall interaction structure.
Prefer generator when the concept is right but the execution needs concrete implementation fixes like labels, wiring, geometry details, styling, or broken controls.

Return ONLY valid JSON with this exact shape:
{
	"next_step": "pass | fix_plan | refine_generation",
	"rationale": "one concise sentence explaining the decision"
}

CALIBRATION EXAMPLES — the decision turns on the failure modes, the five scores, and the notes, so only those are shown here.

